 "content": "from collections import Counter, deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = [[False] * w for _ in range(h)]
    comps = []
    # Find 4-connected same-color components; singleton components are the
    # small stray marks, regardless of how often that color occurs elsewhere.
    for r in range(h):
        for c in range(w):
            if seen[r][c]:
                continue
            color = grid[r][c]
            seen[r][c] = True
            q = deque([(r, c)])
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            comps.append((color, cells))
    for color, cells in comps:
        if len(cells) != 1:
            continue
        r, c = cells[0]
        vals = [grid[y][x]
                for y in range(max(0, r-1), min(h, r+2))
                for x in range(max(0, c-1), min(w, c+2))
                if (y, x) != (r, c)]
        counts = Counter(vals)
        top = max(counts.values())
        out[r][c] = next(v for v in vals if counts[v] == top)
    return out


